  assert.match(html, /<p class="kit-empty__title">No deploys in staging<\/p>/);
  assert.doesNotMatch(html, /<table/);
  assert.match(renderDeploys({ ...snapshot, deploys: [] }, {}), /<p class="kit-empty__title">No deploys<\/p>/);
});

